using System.Diagnostics;

class Test
{
    [Conditional("DEBUG")]
    public virtual void Conditional()
    {
    }
}

class T1 : Test
{
    public override void Conditional()
    {
    }
}

delegate void D1();

class T5
{
    static void Main()
    {
        T1 t1 = new T1();

        D1 d1 = new D1(t1.Conditional);
    }
}

